    f_pointer: ?*anyopaque,
    f_padding: [8]u8,

    /// Returns a newly heap allocated empty string.
    extern fn gst_id_str_new() *gst.IdStr;
    pub const new = gst_id_str_new;

    extern fn gst_id_str_as_str(p_s: *const IdStr) [*:0]const u8;
    pub const asStr = gst_id_str_as_str;

    /// Clears `s` and sets it to the empty string.
    extern fn gst_id_str_clear(p_s: *IdStr) void;
    pub const clear = gst_id_str_clear;

    /// Copies `s` into newly allocated heap memory.
    extern fn gst_id_str_copy(p_s: *const IdStr) *gst.IdStr;
    pub const copy = gst_id_str_copy;

    /// Copies `s` into `d`.
    extern fn gst_id_str_copy_into(p_d: *IdStr, p_s: *const gst.IdStr) void;
    pub const copyInto = gst_id_str_copy_into;

    /// Frees `s`. This should only be called for heap-allocated `gst.IdStr`.
    extern fn gst_id_str_free(p_s: *IdStr) void;
    pub const free = gst_id_str_free;

    /// Returns the length of `s`, exluding the NUL-terminator. This is equivalent to
    /// calling ``strcmp`` but potentially faster.
    extern fn gst_id_str_get_len(p_s: *const IdStr) usize;
    pub const getLen = gst_id_str_get_len;

    /// Initializes a (usually stack-allocated) id string `s`. The newly-initialized
    /// id string will contain an empty string by default as value.
    extern fn gst_id_str_init(p_s: *IdStr) void;
    pub const init = gst_id_str_init;

    /// Compares `s1` and `s2` for equality.
    extern fn gst_id_str_is_equal(p_s1: *const IdStr, p_s2: *const gst.IdStr) c_int;
    pub const isEqual = gst_id_str_is_equal;

    /// Compares `s1` and `s2` for equality.
    extern fn gst_id_str_is_equal_to_str(p_s1: *const IdStr, p_s2: [*:0]const u8) c_int;
    pub const isEqualToStr = gst_id_str_is_equal_to_str;

    /// Compares `s1` and `s2` with length `len` for equality. `s2` does not have to be
    /// NUL-terminated and `len` should not include the NUL-terminator.
    ///
    /// This is generally faster than `gst.IdStr.isEqualToStr` if the length is
    /// already known.
    extern fn gst_id_str_is_equal_to_str_with_len(p_s1: *const IdStr, p_s2: [*:0]const u8, p_len: usize) c_int;
    pub const isEqualToStrWithLen = gst_id_str_is_equal_to_str_with_len;

    /// Moves `s` into `d` and resets `s`.
    extern fn gst_id_str_move(p_d: *IdStr, p_s: *gst.IdStr) void;
    pub const move = gst_id_str_move;

    /// Sets `s` to the string `value`.
    extern fn gst_id_str_set(p_s: *IdStr, p_value: [*:0]const u8) void;
    pub const set = gst_id_str_set;

    /// Sets `s` to the string `value`. `value` needs to be valid for the remaining
