    /// or if the element wasn't found.
    extern fn gst_iterator_find_custom(p_it: *Iterator, p_func: glib.CompareFunc, p_elem: *gobject.Value, p_user_data: ?*anyopaque) c_int;
    pub const findCustom = gst_iterator_find_custom;

