        @setEvalBranchQuota(100_000);
        std.testing.refAllDecls(@This());
    }
};

/// The `gst.MetaInfo` provides information about a specific metadata
/// structure.
pub const MetaInfo = extern struct {
    /// tag identifying the metadata structure and api
