    ///
    /// Free-function: `gst.Query.unref`
    extern fn gst_query_new_seeking(p_format: gst.Format) *gst.Query;
    pub const newSeeking = gst_query_new_seeking;

    /// Constructs a new segment query object. Use `gst.Query.unref`
